                  t -> new PersistedVenue(t._1(), t._2()), pv -> Tuple.of(pv.id(), pv.venue())));

  static OperationRead.Query<PersistedVenue> insert(Venue venue) {
    return Fragment.insertOneReturning("venue", venueCodec, venue, persistedVenueCodec);
