// Process rows lazily without loading all into memory
def countExpensiveProducts(): Long =
  val streaming = Fragment
    .of("SELECT price FROM products")
    .streamingQuery(PgTypes.int4, 512)

  streaming
    .map { cursor =>
      cursor.count(_ > 100).toLong
    }
    .transact(tx)

// Parse at most one result - returns Option[Person]
val singleParser: ResultSetParser[Option[Person]] = personCodec.maxOne()

// Parse all results as a list
val listParser: ResultSetParser[List[Person]] = personCodec.all()

// Execute with ResultSet
def parse(): Option[Person] =
  singleParser.apply(resultSet)

// Multiple reads in one session — same connection, same transaction
case class Dashboard(users: List[User], count: Long, recent: List[User])

// ConnectionRead is available implicitly inside transactRead { }
def dashboard(): Dashboard =
  tx.transactRead {
    val users = findAll.run
    val count = countUsers.run
    val recent = findRecent.run
    Dashboard(users, count, recent)
  }

// Single read operation — no transaction overhead
def allUsers(): List[User] =
  findAll.transactRead(tx)

// Combining read-only operations yields OperationRead
val bothReads: OperationRead[(List[Int], Long)] =
  findIds.combine(countUsers)

// Mixing in a write operation yields Operation (not OperationRead)
val writeAndRead: Operation[(Int, List[Int])] =
  insertUser.combine(findIds)

// transactRead works for read-only compositions
val readResult: (List[Int], Long) = bothReads.transactRead(tx)

// transact required when writes are involved
val writeResult: (Int, List[Int]) = writeAndRead.transact(tx)

def slowQueryDetector(threshold: Duration): QueryListener =
  new QueryListener:
    override def beforeQuery(sql: String, name: java.util.Optional[String]): Unit = ()
    override def afterQuery(event: QueryEvent): Unit =
      if event.elapsed().compareTo(threshold) > 0 then System.err.println(s"SLOW QUERY [${event.elapsed().toMillis}ms]: ${event.interpolatedSql()}")
    override def failedQuery(event: QueryEvent): Unit = ()

