// Insert and return the new user (id + name).
def insertUser(name: String): OperationRead[NewUser] =
  Fragment
    .of("INSERT INTO users(name) VALUES(")
    .value(PgTypes.text, name)
    .append(") RETURNING id, name")
    .query(newUserCodec.exactlyOne())

// Log the creation, taking the new user as input.
def logCreation(user: NewUser): Operation[Int] =
  Fragment
    .of("INSERT INTO audit_log(user_id, username) VALUES(")
    .value(PgTypes.int4, user.id)
    .append(", ")
    .value(PgTypes.text, user.name)
    .append(")")
    .update()

// Chain: insertUser → returned NewUser → logCreation.
def insertAndLog(): Int =
  insertUser("Alice").andThen(user => logCreation(user)).transact(tx)

// Reusable queries as methods
def insertUser(name: String): OperationRead[Int] =
  Fragment
    .of("INSERT INTO users(name) VALUES(")
    .value(PgTypes.text, name)
    .append(") RETURNING id")
    .query(RowCodec.of(PgTypes.int4).exactlyOne())

def ordersByUser(userId: Int): OperationRead[List[Order]] =
  Fragment
    .of("SELECT id, user_id, product FROM orders WHERE user_id = ")
    .value(PgTypes.int4, userId)
    .query(orderCodec.all())

// Chain: insert user, then use returned id to fetch their orders.
def insertAndFetchOrders(): List[Order] =
  insertUser("Alice").andThen(id => ordersByUser(id)).transact(tx)

val countUsers: OperationRead[Long] =
  sql"SELECT count(*) FROM users"
    .query(RowCodec.of(PgTypes.int8).exactlyOne())
val recentOrders: OperationRead[List[Order]] =
  sql"SELECT * FROM orders ORDER BY id DESC LIMIT 10"
    .query(orderCodec.all())

// Run both in one transaction using a transact block
// Connection is available implicitly inside transact { }
def dashboard(): Dashboard = tx.transact {
  val count = countUsers.run
  val orders = recentOrders.run
  Dashboard(count, orders)
}

// For databases without RETURNING (DB2, Oracle, SQL Server, MariaDB):
def insertGeneratedKey(product: Product)(using Connection): Int =
  Fragment
    .insertOneGenerated(
      "product", productCodec, product,
      Array("id"), RowCodec.of(PgTypes.int4).exactlyOne(), "id"
    )
    .run

def insert(product: Product)(using Connection): Product =
  Fragment.insertOneReturning("product", productCodec, product).run

// Skip columns with database defaults — pass column names to except
def insertWithDefault(product: Product)(using Connection): Product =
  Fragment.insertOneReturning("product", productCodec, product, "id").run

// Compose dynamic filters with the `optionally` DSL. Each `.optionally().append(...)`
// is a branch point Query Analysis verifies against the schema, even when
// the runtime never takes that branch at this call site.
def query(): List[ProductRow] =
  sql"SELECT id, name, price FROM product WHERE 1 = 1"
    .optionally(namePattern).append(" AND name ILIKE ", PgTypes.text)
    .optionally(maxPrice).append(" AND price < ", PgTypes.numeric)
    .query(rowCodec.all())
    .transact(tx)

// Dynamic UPDATE — only set the fields that changed
def updateUser(userId: Int, newName: Option[String], newEmail: Option[String])(using Connection): Unit =
  val sets = List(
    newName.map(n => sql"name = ${PgTypes.text(n)}"),
    newEmail.map(e => sql"email = ${PgTypes.text(e)}")
  ).flatten

  if sets.nonEmpty then
    sql"UPDATE users ${Fragment.set(sets)} WHERE id = ${PgTypes.int4(userId)}"
      .update()
      .run

val query: Fragment =
  sql"""SELECT * FROM users
        WHERE id = ${PgTypes.int4(userId)}
        AND status = ${PgTypes.text("active")}
        AND created_at > ${PgTypes.timestamptz(cutoffDate)}"""

// Parameters are bound, not interpolated
def users(using Connection): List[User] =
  query.query(userCodec.all()).run

// Single-operation form: .transact(tx) handles commit/rollback/close.
def cities(): List[City] = findCities.transact(tx)

// Multiple operations in one transaction: compose with combineWith.
def citiesWithCount(): List[City] =
  findCities
    .combineWith(countCities) { (list, count) =>
      println(s"rows: $count")
      list
    }
    .transact(tx)

// Inner join — both sides always present
val innerJoined: RowCodec[(ProductRow, CategoryRow)] =
  productCodec.join(categoryCodec)

// Left join — right side is Option
val leftJoined: RowCodec[(ProductRow, Option[CategoryRow])] =
  productCodec.leftJoin(categoryCodec)

// Batch insert — all columns as parameters
// Connection is provided implicitly by the caller (e.g. inside transact { })
def insertProducts(products: List[Product])(using Connection): Option[Array[Int]] =
  Fragment.insertMany("product", productCodec, products.iterator).run

// Batch insert — skip auto-generated ID column
def insertProductsAutoId(products: List[Product])(using Connection): Option[Array[Int]] =
  Fragment.insertMany("product", productCodec, products.iterator, "id").run
